        t = _column(result, "time")
        n = len(t)
        sig = {}

        def col(name):
            if name == "time":
                return t
            if name in sig:
                return sig[name]
            return _column(result, name)

        _check_derived(result, "q")
        sig["q"] = _vec(col("x") / 0, n)
        trig = []
        segs = _segments({"kind": "all"}, trig, t, None, params)
        v = _calc({"kind": "max", "signal": "q"}, "all", segs, t, col("q"), None, params)
        v = _post(v, {"abs": False, "negate": False, "scale": 1}, params)
        if not np.isfinite(v):
            raise ValueError(_NON_FINITE)
    return float(v)
